DROP TABLE IF EXISTS `brace_major`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `brace_major` (
  `id` bigint(20) NOT NULL COMMENT '主键id',
  `supervision_mark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '所属监督管理部(标识)',
  `major_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '专业名称',
  `flag_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '标识编号',
  `major_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '专业编码(系统生成)',
  `custom_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '自定义编码（用户输入）',
  `major_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '专业路径',
  `grade` int(11) DEFAULT NULL COMMENT '级别',
  `major_status` tinyint(1) DEFAULT '0' COMMENT '专业状态;0.启用1.禁用',
  `parent_id` bigint(20) DEFAULT NULL COMMENT '父专业',
  `insert_person_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '插入操作人的唯一编码',
  `insert_person_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '插入操作人名称',
  `insert_time` datetime DEFAULT NULL COMMENT '插入的时间',
  `last_update_person_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新操作人的唯一编码',
  `last_update_person` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新操作人名称',
  `last_update_time` datetime DEFAULT NULL COMMENT '最后更新的时间',
  `data_level` tinyint(1) DEFAULT NULL COMMENT '数据级别    0可删除可修改 1可修改不可删除 2不可删除不可修改',
  `apply_state` tinyint(1) DEFAULT NULL COMMENT '审批状态  0 不通过 1 通过',
  `apply_person_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审批人',
  `apply_person_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审批人ID',
  `task_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '任务ID',
  `if_need_apply` bit(1) DEFAULT NULL COMMENT '是否需要审批 0 不需要 1 需要',
  `del_flag` bit(1) DEFAULT b'0' COMMENT '逻辑删除 0 未删除 1 已删除',
  `data_scope_user_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '数据权限归属用户ID',
  `data_scope_dept_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '数据权限归属部门Code',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='专业表';
