--
-- Table structure for table `dic_type`
--

DROP TABLE IF EXISTS `dic_type`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `dic_type` (
  `dic_type_id` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '主键',
  `dic_type_code` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '查询唯一码',
  `dic_type_search_code` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '快捷搜索简码6位以内',
  `dic_type_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '名称',
  `dic_type_show_ctx` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '显示内容',
  `dic_type_show_i18n_key` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '国际化key',
  `note` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '描述',
  `has_dics` tinyint(1) DEFAULT NULL COMMENT '是否有字典选项',
  `dic_size` int(11) DEFAULT '0' COMMENT '字典选项数量',
  `dic_item_class` int(11) DEFAULT NULL COMMENT '字典值类型:0：范围、1：枚举、2：树状',
  `default_btn_cls` int(11) DEFAULT NULL COMMENT '页面控件实现样式:0：下拉框、1：复选框组、2：输入框',
  `is_auto_gen` tinyint(1) DEFAULT NULL COMMENT '自动生成开关',
  `is_use_cache` tinyint(1) DEFAULT NULL COMMENT '自动缓存开关',
  `gen_class` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '生成类的包全路径',
  `cache_class` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '缓存类型:redis3、mcache等',
  `static_dics_url` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '生成的json文件的下载地址',
  `id_path` longtext CHARACTER SET utf8 COLLATE utf8_general_ci COMMENT '本层级id路径,例如(当前id为10):1-4-6-10',
  `grade` int(11) DEFAULT NULL COMMENT '当前类型在树结构中的层级',
  `sort` int(11) DEFAULT NULL COMMENT '在当前层级中的顺序',
  `father_id` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '上级ID',
  `son_id_list` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '直接下级的ID列表(有序):11,22,34,56',
  `insert_from_source` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '添加操作的来源:系统编号(从哪个系统过来的)',
  `insert_person_id` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '操作人的唯一编码',
  `insert_time` datetime DEFAULT NULL COMMENT '插入的时间',
  `update_from_source` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '操作的来源:系统编号',
  `last_update_person_id` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '操作人的唯一编码',
  `last_update_time` datetime DEFAULT NULL COMMENT '最后修改的时间',
  `del_from_source` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '操作的来源:系统编号',
  `del_person_id` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '操作人的唯一编码',
  `del_time` datetime DEFAULT NULL COMMENT '逻辑删除的时间',
  `del_flag` tinyint(1) DEFAULT '0' COMMENT '删除状态',
  `status` tinyint(1) DEFAULT '1' COMMENT '启用禁用状态',
  `business_status` int(11) DEFAULT NULL COMMENT '业务中的状态',
  `data_from_source_type` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '本条记录数据来源:系统编号-接口编号、人工上传',
  `data_from_source_id` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '来源的唯一编码,配合data_from_source_type',
  `bus_from_source_type` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '此数据归属(数据级权限控制)',
  `bus_from_source_id` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '此业务数据归属主体的ID',
  `bus_from_source_type_path` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '此业务数据逻辑归属的路径(由高到低):系统-市场-办理机构-业务员',
  `bus_from_source_id_path` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '此业务的归属主体:系统ID-市场ID-机构ID-业务员ID',
  `data_level` tinyint(1) DEFAULT '0' COMMENT '数据级别 0可删除可修改 1可修改不可删除 2不可删除不可修改',
  `data_source_path` json DEFAULT NULL COMMENT '数据来源去向',
  PRIMARY KEY (`dic_type_id`) USING BTREE,
  KEY `FK_Reference_2` (`father_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='字典类型';
/*!40101 SET character_set_client = @saved_cs_client */;

